import{_ as e,o,c as a,a2 as i}from"./chunks/framework.Ce1WstT_.js";const m=JSON.parse('{"title":"18. Limitations & Future Scope","description":"","frontmatter":{},"headers":[],"relativePath":"project/limitations.md","filePath":"project/limitations.md"}'),n={name:"project/limitations.md"};function r(s,t,l,c,u,d){return o(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="_18-limitations-future-scope" tabindex="-1">18. Limitations &amp; Future Scope <a class="header-anchor" href="#_18-limitations-future-scope" aria-label="Permalink to &quot;18. Limitations &amp; Future Scope&quot;">​</a></h1><p>While the application supports the core operational loops, several areas offer clear expansion opportunities.</p><h2 id="known-ui-limitations" tabindex="-1">Known UI Limitations <a class="header-anchor" href="#known-ui-limitations" aria-label="Permalink to &quot;Known UI Limitations&quot;">​</a></h2><ul><li><strong>Multi-Item UI</strong>: The backend fully supports drafting challans with an array of multiple items, however, the current React implementation limits adding only a single product item via the wizard at a time.</li><li><strong>Editing Entities</strong>: The backend API contains <code>PUT</code> endpoints for editing Customer details and Product catalog parameters, but UI Modals for these operations are not yet mapped to the DOM.</li><li><strong>Dynamic User Setup</strong>: The <code>/users</code> endpoint for Admins to create new staff accounts is conceptually defined but unimplemented; current users rely on database seeds.</li></ul><h2 id="future-architectural-scope" tabindex="-1">Future Architectural Scope <a class="header-anchor" href="#future-architectural-scope" aria-label="Permalink to &quot;Future Architectural Scope&quot;">​</a></h2><ul><li><strong>Multi-Warehouse Support</strong>: Moving from a simple <code>location</code> string field on the <code>products</code> table to a many-to-many <code>warehouse_inventory</code> junction table.</li><li><strong>Billing Integration</strong>: Confirmed Challans can easily serve as origin documents for a future <code>invoices</code> table to track accounts receivable.</li><li><strong>Background Jobs</strong>: Implementing Redis + BullMQ for asynchronous PDF generation (Challan printing) and low-stock email dispatching.</li></ul>',6)])])}const h=e(n,[["render",r]]);export{m as __pageData,h as default};
